// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(address newOwner) public {
        // The test contract is the owner of c (deployed in setUp). Drive c through transferOwnership
        // with a fully fuzzed newOwner (whole address domain, zero address included).
        vm.prank(address(this));
        try c.transferOwnership(newOwner) {
            // transfer accepted: in the reference, newOwner != address(0) was required,
            // so a successful call always leaves a nonzero owner.
            assertTrue(c.owner() != address(0), "owner must never be zero");
        } catch {
            // transfer reverted (e.g. newOwner == address(0) in the reference): the owner is unchanged
            // and remains nonzero (set by the constructor / any prior accepted transfer).
            assertTrue(c.owner() != address(0), "owner must never be zero");
        }
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
